diff_readable:
REPLACE spec.replicas: 1 → 3
REPLACE spec.template.spec.containers[redis].resources.requests.cpu: "100m" → "150m"
REPLACE spec.template.spec.containers[redis].resources.requests.memory: "128Mi" → "192Mi"
ADD spec.template.spec.containers[redis].volumeMounts[7]: {"name": "hostpath-volume", "mountPath": "/mnt/host-var-run-docker.sock"}
ADD spec.template.spec.volumes[5]: {"name": "hostpath-volume", "hostPath": {"path": "/var/run/docker.sock"}}

ADD spec.template.spec.containers[node-exporter].securityContext.runAsNonRoot: true
ADD spec.template.spec.containers[node-exporter].securityContext.runAsUser: 10001
ADD spec.template.spec.containers[node-exporter].env[1]: {"name": "DB_PASSWORD", "value": "pass-1256"}
REMOVE spec.template.spec.containers[node-exporter].livenessProbe: {"failureThreshold": 3, "httpGet": {"httpHeaders": null, "path": "/", "port": "metrics", "scheme": "HTTP"}, "initialDelaySeconds": 0, "periodSeconds": 10, "successThreshold": 1, "timeoutSeconds": 1}

ADD spec.template.metadata.annotations: {"sidecar.istio.io/inject": "true"}
REPLACE spec.template.spec.automountServiceAccountToken: true → false
ADD spec.template.spec.containers[kube-state-metrics].securityContext.runAsUser: 0
